import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';

const outputPath = 'docs/agentic/repo-map.md';

const packageJson = JSON.parse(readFileSync('package.json', 'utf8'));
const trackedFiles = readCommand('git', ['ls-files', '--cached', '--others', '--exclude-standard'])
  .split('\n')
  .filter((filePath) => filePath && existsSync(filePath));

const sections = [
  '# VeloRail Repo Map',
  '',
  'Generated by `npm run agent:repo-map`.',
  '',
  '## App Shape',
  '',
  '- Entry path: `index.html -> src/main.tsx -> src/App.tsx`.',
  '- Frontend: React, TypeScript, Vite, Zustand, React Query.',
  '- Map runtime: Google Maps JavaScript APIs through `@googlemaps/js-api-loader` and `@react-google-maps/api`.',
  '- Routing/data focus: car-free route planning, future transit overlays, visionary/freight/nationalized scenarios, GTFS ingestion, and scoring.',
  '',
  '## Core Commands',
  '',
  ...Object.entries(packageJson.scripts || {}).map(([name, command]) => `- \`npm run ${name}\`: \`${command}\``),
  '',
  '## Main Code Areas',
  '',
  ...summarizeFiles(trackedFiles),
  '',
  '## Agent Workflow',
  '',
  '- Start from `AGENTS.md` and the relevant `.agents/skills/*/SKILL.md` file.',
  '- Use Linear for active task state and GitHub for code review.',
  '- Use `npm run task:gate -- <task-id> --explain` before closing work.',
  '- Browser-facing changes require `npm run test:browser:required` with a task tag or smoke tag.',
  '',
  '## Legacy Archives',
  '',
  'Hidden legacy directories such as `.seeds`, `.mulch`, `.canopy`, `.overstory`, and `.claude` are retained only as migration history. Do not use them as active workflow entrypoints.'
];

writeFileSync(outputPath, `${sections.join('\n')}\n`);
console.log(`Wrote ${outputPath}`);

function summarizeFiles(files) {
  const groups = [
    ['`src/components/`', files.filter((file) => file.startsWith('src/components/')).length],
    ['`src/services/`', files.filter((file) => file.startsWith('src/services/')).length],
    ['`src/data/`', files.filter((file) => file.startsWith('src/data/')).length],
    ['`src/gtfs/`', files.filter((file) => file.startsWith('src/gtfs/')).length],
    ['`src/types/`', files.filter((file) => file.startsWith('src/types/')).length],
    ['`tests/`', files.filter((file) => file.startsWith('tests/')).length],
    ['`tests/browser/`', files.filter((file) => file.startsWith('tests/browser/')).length],
    ['`docs/architecture/`', files.filter((file) => file.startsWith('docs/architecture/')).length]
  ];

  return groups.map(([label, count]) => `- ${label}: ${count} known files`);
}

function readCommand(command, args) {
  return execFileSync(command, args, { encoding: 'utf8' }).trim();
}
